      state <= 1'h0;
      count <= 3'h0;
    end
    else begin
      automatic logic _GEN;
      automatic logic _GEN_0;
      _GEN = ~rdReq | (&count);
      _GEN_0 = ~wrReq | (&count);
      if (state)
        state <= ~_GEN_0;
      else
        state <= _GEN;
      count <= state ? (_GEN_0 ? 3'h0 : count + 3'h1) : _GEN ? 3'h0 : count + 3'h1;
    end
  end // always @(posedge)
  assign chooseRd = ~state;
endmodule

